import data from "@/lib/country-codes-data.json";

/**
 * ISO 3166-1 normalisation for the free-form `varchar(3)` country columns on
 * import cases. The create form stores alpha-2 ("CN"), but extraction or older
 * rows can hold alpha-3 ("CHN"), so both are accepted and mapped to alpha-2.
 *
 * The data file is generated by `scripts/generate-world-map.mjs` (it also holds
 * the projected map centroid of every country).
 */

export type CountryMeta = {
  iso2: string;
  iso3: string;
  name: string;
  /** Centroid in map (viewBox) units. */
  x: number;
  y: number;
  /** True when the 110m world map draws a shape for this country. */
  hasShape: boolean;
};

/** The app is built for Ethiopian customs: every case is an import into Ethiopia. */
export const DESTINATION_ISO2 = "ET";

type Row = [string, string, string, number, number, number];

const BY_ISO2 = new Map<string, CountryMeta>();
const BY_ISO3 = new Map<string, CountryMeta>();

for (const [iso2, iso3, name, x, y, shape] of (data as { countries: Row[] })
  .countries) {
  const meta: CountryMeta = { iso2, iso3, name, x, y, hasShape: shape === 1 };
  BY_ISO2.set(iso2, meta);
  BY_ISO3.set(iso3, meta);
}

/** Common non-ISO or legacy codes seen in trade paperwork. */
const ALIASES_2: Record<string, string> = { UK: "GB", EL: "GR" };
const ALIASES_3: Record<string, string> = { XKX: "XK", ROM: "RO", ZAR: "CD" };

/** Returns the alpha-2 code for an alpha-2 or alpha-3 input, or null when unknown. */
export function normalizeCountryCode(
  raw: string | null | undefined,
): string | null {
  const v = raw?.trim().toUpperCase();
  if (!v) return null;
  if (v.length === 2) {
    const code = ALIASES_2[v] ?? v;
    return BY_ISO2.has(code) ? code : null;
  }
  if (v.length === 3) {
    const alias = ALIASES_3[v];
    if (alias) return BY_ISO2.has(alias) ? alias : null;
    return BY_ISO3.get(v)?.iso2 ?? null;
  }
  return null;
}

export function getCountryMeta(
  raw: string | null | undefined,
): CountryMeta | null {
  const iso2 = normalizeCountryCode(raw);
  return iso2 ? (BY_ISO2.get(iso2) ?? null) : null;
}